import React, { useState } from 'react';

function TimeBlock({ id, title, time, icon, items = [], onUpdate }) {
  const [isEditing, setIsEditing] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState('');
  const [selectedSubcategory, setSelectedSubcategory] = useState('');
  const [selectedTime, setSelectedTime] = useState('30 мин');

  const categories = [
    { name: 'Yoga', subcategories: ['Концентрация', 'Медитация', 'Пранаяма', 'Кумбхака', 'Олень'] },
    { name: 'Boxing', subcategories: ['Стандарт 1', 'Стандарт 2', 'Стандарт 3'] },
    { name: 'SoftDev', subcategories: ['Стандарт 1', 'Стандарт 2', 'Стандарт 3'] },
    { name: 'MBA', subcategories: ['Стандарт 1', 'Стандарт 2', 'Стандарт 3'] },
    { name: 'English', subcategories: ['Стандарт 1', 'Стандарт 2', 'Стандарт 3'] },
    { name: 'Oratory', subcategories: ['Стандарт 1', 'Стандарт 2', 'Стандарт 3'] },
    { name: 'Math', subcategories: ['Стандарт 1', 'Стандарт 2', 'Стандарт 3'] },
    { name: 'Chinise', subcategories: ['Стандарт 1', 'Стандарт 2', 'Стандарт 3'] },
    { name: 'Finance', subcategories: ['Стандарт 1', 'Стандарт 2', 'Стандарт 3'] },
    { name: 'Chess', subcategories: ['Стандарт 1', 'Стандарт 2', 'Стандарт 3'] },
    { name: 'Business', subcategories: ['Стандарт 1', 'Стандарт 2', 'Стандарт 3'] }
  ];

  const timeOptions = [
    '5 мин', '10 мин', '15 мин', '30 мин', '31 мин',
    '60 мин', '90 мин', '120 мин', '180 мин'
  ];

  const addItem = () => {
    if (selectedCategory && selectedSubcategory) {
      const newItem = {
        id: Date.now(),
        category: selectedCategory,
        subcategory: selectedSubcategory,
        time: selectedTime
      };
      onUpdate([...items, newItem]);

      // Сброс формы
      setSelectedCategory('');
      setSelectedSubcategory('');
      setSelectedTime('30 мин');
      setIsEditing(false);
    }
  };

  const removeItem = (itemId) => {
    onUpdate(items.filter(item => item.id !== itemId));
  };

  const getCategoryColor = (category) => {
    const colors = {
      'Yoga': '#9b59b6',
      'Boxing': '#e74c3c',
      'SoftDev': '#3498db',
      'MBA': '#2ecc71',
      'English': '#f1c40f',
      'Oratory': '#e67e22',
      'Math': '#1abc9c',
      'Chinise': '#e84393',
      'Finance': '#27ae60',
      'Chess': '#8e44ad',
      'Business': '#d35400'
    };
    return colors[category] || '#95a5a6';
  };

  const getCurrentCategory = () => {
    return categories.find(c => c.name === selectedCategory);
  };

  const formatTime = (timeString) => {
    return timeString;
  };

  return (
    <div className="time-block" style={{ borderColor: getCategoryColor(items[0]?.category) }}>
      <div className="block-header">
        <span className="block-icon">{icon}</span>
        <h3>{title}</h3>
        <span className="block-time">{time}</span>
      </div>

      <div className="block-content">
        {items.length > 0 ? (
          <ul className="items-list">
            {items.map(item => (
              <li key={item.id} className="item">
                <span
                  className="category-badge"
                  style={{ backgroundColor: getCategoryColor(item.category) }}
                >
                  {item.category}
                </span>
                <span className="subcategory-badge">
                  {item.subcategory}
                </span>
                <span className="time-badge">
                  ⏱️ {item.time}
                </span>
                <button onClick={() => removeItem(item.id)} className="remove-btn">✕</button>
              </li>
            ))}
          </ul>
        ) : (
          <p className="empty-message">Нет записей</p>
        )}

        {isEditing && (
          <div className="add-item-form">
            <select
              value={selectedCategory}
              onChange={(e) => {
                setSelectedCategory(e.target.value);
                setSelectedSubcategory('');
              }}
              className="category-select"
            >
              <option value="">Выберите категорию</option>
              {categories.map(cat => (
                <option key={cat.name} value={cat.name}>{cat.name}</option>
              ))}
            </select>

            {selectedCategory && (
              <select
                value={selectedSubcategory}
                onChange={(e) => setSelectedSubcategory(e.target.value)}
                className="subcategory-select"
              >
                <option value="">Выберите практику</option>
                {getCurrentCategory()?.subcategories.map(sub => (
                  <option key={sub} value={sub}>{sub}</option>
                ))}
              </select>
            )}

            <select
              value={selectedTime}
              onChange={(e) => setSelectedTime(e.target.value)}
              className="time-select"
            >
              {timeOptions.map(time => (
                <option key={time} value={time}>{time}</option>
              ))}
            </select>

            <div className="form-actions">
              <button
                onClick={addItem}
                className="add-btn"
                disabled={!selectedCategory || !selectedSubcategory}
              >
                Добавить
              </button>
              <button
                onClick={() => setIsEditing(false)}
                className="cancel-btn"
              >
                Отмена
              </button>
            </div>
          </div>
        )}

        {!isEditing && (
          <button
            onClick={() => setIsEditing(true)}
            className="toggle-edit-btn"
          >
            + Добавить практику
          </button>
        )}
      </div>
    </div>
  );
}

export default TimeBlock;
